    /// <summary>
    /// MPJ_19962_MDRPOTransactionalMissingFields by kavya on 9/5/2022
    /// </summary>
    /// <param name = "_ChangeReasonCode">reason code</param>
    /// <param name = "_forupdate">Parameter to check for update</param>
    /// <param name = "_concurrencyModel">Model</param>
    /// <returns>Table buffer</returns>
    public static METPOChangeReasonCodeSetup find(
        METChangeReasonCode _ChangeReasonCode ,
        boolean _forupdate = false,
        ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METPOChangeReasonCodeSetup ChangeReasonCodeSetup;

        ChangeReasonCodeSetup.selectForUpdate(_forupdate);
        if (_forupdate && _concurrencyModel != ConcurrencyModel::Auto)
        {
            ChangeReasonCodeSetup.concurrencyModel(_concurrencyModel);
        }

        select firstonly ChangeReasonCodeSetup where ChangeReasonCodeSetup.ChangeReasonCode == _ChangeReasonCode;

        return ChangeReasonCodeSetup;
    }

    /// <summary>
    /// MPJ_19962_MDRPOTransactionalMissingFields - by kavya on 9/5/2022
    /// </summary>
    /// <param name = "_ChangeReasonCode"> reason code</param>
    /// <returns>Boolean value</returns>
    public static boolean exist(METChangeReasonCode _ChangeReasonCode )
    {
        boolean found;

        found = (select firstonly
                     RecId
                from
                     METPOChangeReasonCodeSetup
                 where
                     METPOChangeReasonCodeSetup.ChangeReasonCode == _ChangeReasonCode).RecId != 0;

        return found;
    }
